#!/usr/bin/env bash
# Pedro Veríssimo, the interactive terminal version.
#
#   curl -sL pedroverissimo.vercel.app/go | bash
#   curl -sL pedroverissimo.vercel.app/go | bash -s rockets     (open a page directly)
#
# Arrows or j/k to move, enter to open, ←/→ between pages, tab through the buttons, q to quit. The mouse works too.
# Plain bash 3.2+ and coreutils; nothing is installed or written to disk.
# Generated by tools/build-terminal.py from tools/terminal-tui.sh; edit those, not go.sh.

pv_data() {
@@DATA@@
}

pv_size() {
  local s; s=$(stty size <&3 2>/dev/null)
  ROWS=${s% *} COLS=${s#* }
  case "$ROWS$COLS" in ''|*[!0-9]*) ROWS=$(tput lines 2>/dev/null || echo 24) COLS=$(tput cols 2>/dev/null || echo 80) ;; esac
  VH=$((ROWS - 5))
  X0=$(( (COLS - CW) / 2 + 1 )); [ $X0 -lt 1 ] && X0=1
  MX=$(( (COLS - MW) / 2 + 1 )); [ $MX -lt 1 ] && MX=1
  PX=$((MX + 28))
  TALL=; [ $ROWS -ge $((AH[BANNER] + NP + 7)) ] && TALL=1
  LY=3; [ -n "$TALL" ] && LY=$((AH[BANNER] + 4))
  if [ $COLS -lt $MINC ] || [ $ROWS -lt $MINR ]; then
    [ "$MODE" != small ] && { SMALLOF=$MODE; MODE=small; }
  elif [ "$MODE" = small ]; then MODE=$SMALLOF
  fi
  CLEAR=1 DIRTY=1
}

pv_read() { KB=$(dd bs=64 count=1 <&3 2>/dev/null; printf .); KB=${KB%.}; }
pv_at() { O+=$'\e['"$1;$2H"; }
pv_flush() { printf '%s' $'\e[?2026h'"$O"$'\e[?2026l'; O=; }

# R = row $3 of frame $2 of animation $1; looping animations wrap, the others hold their last frame
pv_row() {
  local a=$1 f=$2 n=${AN[$1]}
  if [ "${ALP[$a]}" = 1 ]; then f=$((f % n)); elif [ $f -ge $n ]; then f=$((n - 1)); fi
  R=${U[${FI[$((AS[a] + f * AH[a] + $3))]}]}
}

pv_say() { MSG=$1; MSGT=$((F + 40)); }

pv_url() {
  if [ "$(uname)" = Darwin ] && command -v open >/dev/null 2>&1; then (open "$1" >/dev/null 2>&1 &)
  elif command -v xdg-open >/dev/null 2>&1; then (xdg-open "$1" >/dev/null 2>&1 &)
  elif command -v wslview >/dev/null 2>&1; then (wslview "$1" >/dev/null 2>&1 &)
  else pv_say "copy this: $1"; return; fi
  pv_say "↗ opened $1"
}

# ------------------------------------------------------------------------------------------- footer
# Buttons for the current screen: labels BTL, widths BTW, actions BTA; drawn with their x ranges in BX0/BX1
pv_buttons() {
  local i x=$1 col=$3
  pv_at "$2" "$x"
  for ((i = 0; i < NB; i++)); do
    if [ "${BTA[i]}" = '|' ]; then O+=$'\e[38;2;58;61;70m│\e[0m '; BX0[i]=-1 BX1[i]=-1; x=$((x + 2)); continue; fi
    if [ $i = "$FOC" ]; then O+=$'\e[1;38;2;10;11;15;48;2;'"${col}m ${BTL[i]} "$'\e[0m '
    else O+=$'\e[38;2;233;236;242;48;2;36;38;46m'" ${BTL[i]} "$'\e[0m '; fi
    BX0[i]=$x; x=$((x + BTW[i] + 2)); BX1[i]=$((x - 1)); x=$((x + 1))
  done
  O+=$'\e[K'
}

pv_hint() {
  pv_at "$ROWS" "$1"
  if [ "$MSGT" -gt "$F" ]; then O+=$'\e[38;2;46;230;166m'"$MSG"$'\e[0m\e[K'; else O+="$2"$'\e[K'; fi
}

pv_hit() {  # x -> index of the footer button under it, or -1
  local i; HIT=-1
  for ((i = 0; i < NB; i++)); do [ "$1" -ge "${BX0[i]}" ] && [ "$1" -le "${BX1[i]}" ] && [ "${BX0[i]}" -ge 0 ] && { HIT=$i; return; }; done
}

# ------------------------------------------------------------------------------------------- intro
pv_intro() {
  local f=$((F - AF0)) r x=$(( (COLS - 68) / 2 + 1 )) y=$(( (ROWS - 21) / 2 + 1 ))
  [ $y -lt 1 ] && y=1
  if [ $f -ge "$INTRO_END" ]; then pv_menu_go; return; fi
  for ((r = 0; r < ${AH[LAUNCH]}; r++)); do pv_row "$LAUNCH" "$f" "$r"; pv_at $((y + r)) "$x"; O+="$R"; done
  pv_row "$CAPTION" "$f" 0; pv_at $((y + ${AH[LAUNCH]} + 1)) $((x + 2)); O+="$R"$'\e[K'
  pv_at $((y + ${AH[LAUNCH]} + 2)) $((x + 2)); O+="$SKIP"$'\e[K'
  pv_flush
}

# ------------------------------------------------------------------------------------------- menu
pv_menu_go() {
  MODE=menu AF0=$F BF0=$F CLEAR=1 DIRTY=1 FOC=-1
  NB=${#MBL[@]}; BTL=("${MBL[@]}"); BTW=("${MBW[@]}"); BTA=("${MBA[@]}")
}

pv_preview() {  # $1 = 1 to draw the text too
  local a=${PVA[SEL]} r h y
  h=${AH[a]}
  for ((r = 0; r < h; r++)); do pv_row "$a" $((F - AF0)) "$r"; pv_at $((LY + r)) "$PX"; O+="$R"$'\e[K'; done
  [ "$1" = 1 ] || return
  y=$((LY + h + 1)); pv_at $((LY + h)) "$PX"; O+=$'\e[K'
  for ((r = MDS[SEL]; r < MDS[SEL] + MDN[SEL]; r++)); do pv_at $y "$PX"; O+="${MD[r]}"$'\e[K'; y=$((y + 1)); done
  while [ $y -lt $((LY + NP)) ]; do pv_at $y "$PX"; O+=$'\e[K'; y=$((y + 1)); done
}

pv_banner() {
  local r
  [ -n "$TALL" ] || return
  for ((r = 0; r < AH[BANNER]; r++)); do pv_row "$BANNER" $((F - BF0)) "$r"; pv_at $((3 + r)) "$MX"; O+="$R"$'\e[K'; done
}

pv_menu() {
  local i
  [ -n "$CLEAR" ] && O+=$'\e[2J'; CLEAR=
  pv_at 1 "$MX"; O+="$MHEAD"$'\e[K'; pv_at 2 "$MX"; O+="$MRULE"
  pv_banner
  for ((i = 0; i < NP; i++)); do
    pv_at $((LY + i)) "$MX"
    if [ $i = "$SEL" ]; then O+="${MSL[i]}"; else O+="${ML[i]}"; fi
  done
  pv_preview 1
  pv_at $((ROWS - 2)) "$MX"; O+="$MRULE"
  pv_buttons $((MX + 1)) $((ROWS - 1)) '79;127;255'
  pv_hint "$MX" "$MHINT"
  pv_flush
}

pv_menu_tick() { pv_banner; pv_preview 0; pv_hint "$MX" "$MHINT"; pv_flush; }

pv_menu_key() {
  case $1 in
    up|k|K) SEL=$(( (SEL + NP - 1) % NP )) AF0=$F DIRTY=1 ;;
    down|j|J|tab) SEL=$(( (SEL + 1) % NP )) AF0=$F DIRTY=1 ;;
    btab) SEL=$(( (SEL + NP - 1) % NP )) AF0=$F DIRTY=1 ;;
    home|g) SEL=0 AF0=$F DIRTY=1 ;;
    end|G) SEL=$((NP - 1)) AF0=$F DIRTY=1 ;;
    enter|right|l|space) pv_page_go "$SEL" ;;
    *) pv_menu_act "$1" "$2" "$3" "$4" ;;
  esac
}

pv_menu_act() {
  case $1 in
    o|O) pv_url "https://$SITE" ;;
    r|R) pv_intro_go ;;
    '?') pv_overlay help ;;
    q|Q) QUIT=1 ;;
    mouse)
      case $2 in
        64) pv_menu_key up ;; 65) pv_menu_key down ;;
        0)
          if [ "$4" -ge "$LY" ] && [ "$4" -lt $((LY + NP)) ] && [ "$3" -ge "$MX" ] && [ "$3" -lt "$PX" ]; then pv_page_go $(($4 - LY))
          elif [ "$4" -ge "$LY" ] && [ "$4" -lt $((LY + NP)) ] && [ "$3" -ge "$PX" ]; then pv_page_go "$SEL"
          elif [ "$4" = $((ROWS - 1)) ]; then pv_hit "$3"; [ $HIT -ge 0 ] && pv_menu_act "${BTA[HIT]}"
          fi ;;
      esac ;;
    open) pv_page_go "$SEL" ;;
    launch) pv_intro_go ;;
    web) pv_url "https://$SITE" ;;
    help) pv_overlay help ;;
    quit) QUIT=1 ;;
  esac
}

pv_intro_go() { MODE=intro AF0=$F CLEAR=1 DIRTY=1; }

# ------------------------------------------------------------------------------------------- pages
pv_page_go() {
  local i
  PG=$1 SEL=$1 SC=0 AF0=$F BF0=$F MODE=page CLEAR=1 DIRTY=1
  NB=${BN[PG]}; BTL=() BTW=() BTA=()
  for ((i = 0; i < NB; i++)); do BTL[i]=${BL[BS[PG] + i]}; BTW[i]=${BW[BS[PG] + i]}; BTA[i]=${BA[BS[PG] + i]}; done
  FOC=2
}

pv_body() {  # $1 = 1 to redraw only the animated lines
  local i r l s a start=${PS[PG]} n=${PN[PG]}
  for ((i = 0; i < VH; i++)); do
    r=$((SC + i))
    if [ $r -ge "$n" ]; then [ "$1" = 1 ] || { pv_at $((3 + i)) "$X0"; O+=$'\e[K'; }; continue; fi
    l=${PL[start + r]}
    case $l in
      @a*) s=${l#@a}; a=${s%% *}
        if [ "${s#* }" = t ]; then pv_row "$a" $((F - BF0)) 0; else pv_row "$a" $((F - AF0)) "${s#* }"; fi
        pv_at $((3 + i)) "$X0"; O+="  $R"$'\e[K' ;;
      *) [ "$1" = 1 ] || { pv_at $((3 + i)) "$X0"; O+="$l"$'\e[K'; } ;;
    esac
  done
}

pv_scrollbar() {
  local n=${PN[PG]} p
  pv_at $((ROWS - 2)) "$X0"
  if [ "$n" -le "$VH" ]; then O+="$RULE"; return; fi
  p=$(( SC * 100 / (n - VH) ))
  O+="${RULE_S}"$'\e[38;2;140;146;160m'
  if [ $SC = 0 ]; then O+='  ↓ more '; elif [ $p -ge 100 ]; then O+='   ↑ end '; else O+=$(printf ' ↕ %3d%% ' $p); fi
  O+=$'\e[0m'
}

pv_page() {
  [ -n "$CLEAR" ] && O+=$'\e[2J'; CLEAR=
  pv_at 1 "$X0"; O+="${PH[PG]}"$'\e[K'; pv_at 2 "$X0"; O+="$RULE"
  pv_body 0
  pv_scrollbar
  pv_buttons $((X0 + 2)) $((ROWS - 1)) "${PC[PG]}"
  pv_hint "$X0" "$PHINT"
  pv_flush
}

pv_page_tick() { pv_body 1; pv_hint "$X0" "$PHINT"; pv_flush; }

pv_scroll() {
  local max=$((PN[PG] - VH))
  [ $max -lt 0 ] && max=0
  SC=$((SC + $1)); [ $SC -gt $max ] && SC=$max; [ $SC -lt 0 ] && SC=0
  DIRTY=1
}

pv_page_key() {
  case $1 in
    up|k|K) pv_scroll -1 ;;
    down|j|J) pv_scroll 1 ;;
    pgup|b|B) pv_scroll $((2 - VH)) ;;
    pgdn|space) pv_scroll $((VH - 2)) ;;
    home|g) pv_scroll -99999 ;;
    end|G) pv_scroll 99999 ;;
    left|h|H) pv_page_go $(( (PG + NP - 1) % NP )) ;;
    right|l|L) pv_page_go $(( (PG + 1) % NP )) ;;
    tab) FOC=$(( (FOC + 1) % NB )); [ "${BTA[FOC]}" = '|' ] && FOC=$(( (FOC + 1) % NB )); DIRTY=1 ;;
    btab) FOC=$(( (FOC + NB - 1) % NB )); [ "${BTA[FOC]}" = '|' ] && FOC=$(( (FOC + NB - 1) % NB )); DIRTY=1 ;;
    enter) pv_page_act "${BTA[FOC]}" ;;
    esc|back|m|M) pv_menu_go ;;
    o|O) pv_url "https://$SITE/#${PA[PG]}" ;;
    r|R) AF0=$F BF0=$F DIRTY=1 ;;
    '?') pv_overlay help ;;
    q|Q) QUIT=1 ;;
    mouse)
      case $2 in
        64) pv_scroll -3 ;; 65) pv_scroll 3 ;;
        0) [ "$4" = $((ROWS - 1)) ] && { pv_hit "$3"; [ $HIT -ge 0 ] && { FOC=$HIT; pv_page_act "${BTA[HIT]}"; }; } ;;
      esac ;;
  esac
}

pv_page_act() {
  case $1 in
    prev) pv_page_go $(( (PG + NP - 1) % NP )) ;;
    next) pv_page_go $(( (PG + 1) % NP )) ;;
    menu) pv_menu_go ;;
    replay) AF0=$F SC=0 DIRTY=1 ;;
    web) pv_url "https://$SITE/#${PA[PG]}" ;;
    url:*) pv_url "${1#url:}" ;;
  esac
}

# ------------------------------------------------------------------------------------------- overlays
pv_overlay() { [ "$MODE" = egg ] || [ "$MODE" = help ] || BACK=$MODE; MODE=$1 AF0O=$F DIRTY=1; }

pv_box() {  # draws animation $1 centred, frame $2
  local a=$1 r w=${AW[$1]} h=${AH[$1]} x y
  x=$(( (COLS - w) / 2 + 1 )) y=$(( (ROWS - h) / 2 + 1 ))
  for ((r = 0; r < h; r++)); do pv_row "$a" "$2" "$r"; pv_at $((y + r)) "$x"; O+="$R"; done
  pv_flush
}

pv_overlay_key() {
  case $1 in mouse) case $2 in 0) ;; *) return ;; esac ;; esac
  MODE=$BACK CLEAR=1 DIRTY=1
  [ "$MODE" = page ] || [ "$MODE" = menu ] || pv_menu_go
}

# ------------------------------------------------------------------------------------------- loop
pv_events() {
  local s=$KB t b x y k
  while [ -n "$s" ]; do
    case $s in
      $'\e[<'*)
        t=${s:3}; t=${t%%[Mm]*}; s=${s:$((3 + ${#t}))}; k=${s:0:1}; s=${s:1}
        b=${t%%;*} t=${t#*;}; x=${t%%;*} y=${t#*;}
        [ "$k" = M ] && pv_key mouse "$b" "$x" "$y" ;;
      $'\e[A'*|$'\eOA'*) pv_key up; s=${s:3} ;;
      $'\e[B'*|$'\eOB'*) pv_key down; s=${s:3} ;;
      $'\e[C'*|$'\eOC'*) pv_key right; s=${s:3} ;;
      $'\e[D'*|$'\eOD'*) pv_key left; s=${s:3} ;;
      $'\e[H'*|$'\eOH'*) pv_key home; s=${s:3} ;;
      $'\e[F'*|$'\eOF'*) pv_key end; s=${s:3} ;;
      $'\e[Z'*) pv_key btab; s=${s:3} ;;
      $'\e[M'*) s=${s:6} ;;
      $'\e[5~'*) pv_key pgup; s=${s:4} ;;
      $'\e[6~'*) pv_key pgdn; s=${s:4} ;;
      $'\e['*) s=${s:2}; s=${s#*[~A-Za-z]} ;;
      $'\e'*) pv_key esc; s=${s:1} ;;
      $'\t'*) pv_key tab; s=${s:1} ;;
      $'\n'*|$'\r'*) pv_key enter; s=${s:1} ;;
      ' '*) pv_key space; s=${s:1} ;;
      $'\x7f'*|$'\b'*) pv_key back; s=${s:1} ;;
      *) pv_key "${s:0:1}"; s=${s:1} ;;
    esac
  done
}

pv_key() {
  case $1 in
    [0-9]) DIG=$DIG$1; [ ${#DIG} -gt 4 ] && DIG=${DIG:1}; [ "$DIG" = 1155 ] && { DIG=; pv_overlay egg; return; } ;;
  esac
  case $MODE in
    intro) [ "$1" = q ] && QUIT=1 || pv_menu_go ;;
    egg|help) pv_overlay_key "$@" ;;
    small) case $1 in q|Q|esc) QUIT=1 ;; esac ;;
    menu) pv_menu_key "$@" ;;
    page) pv_page_key "$@" ;;
  esac
}

pv_small() {
  O+=$'\e[2J'; pv_at $((ROWS / 2)) 3
  O+=$'\e[1mmake the window a bit bigger\e[0m'; pv_at $((ROWS / 2 + 1)) 3
  O+=$'\e[2m'"at least ${MINC}×${MINR}, it's ${COLS}×${ROWS} now · q to quit"$'\e[0m'
  pv_flush
}

pv_bye() {
  printf '\e[?1000l\e[?1006l\e[0m\e[?7h\e[?25h\e[?1049l'
  [ -n "$STTY" ] && stty "$STTY" <&3 2>/dev/null
  printf '%s\n' "$BYE"
}

pv_main() {
  if [ ! -t 1 ] || ! { exec 3</dev/tty; } 2>/dev/null; then
    echo "This one needs an interactive terminal. The plain version: curl -sL pedroverissimo.vercel.app"; exit 1
  fi
  pv_data
  STTY=$(stty -g <&3)
  trap pv_bye EXIT
  trap 'exit 130' INT TERM HUP
  trap 'WINCHED=1' WINCH
  stty -echo -icanon min 0 time 1 <&3
  printf '\e[?1049h\e[?7l\e[?25l\e[?1000h\e[?1006h'
  F=0 AF0=0 BF0=0 SEL=0 PG=0 SC=0 FOC=-1 NB=0 MSGT=0 DIG= QUIT= MODE=intro
  local i
  if [ -n "$1" ]; then for ((i = 0; i < NP; i++)); do [ "${PSL[i]}" = "$1" ] && { SEL=$i; MODE=page; }; done; fi
  pv_size
  case $MODE in page) pv_page_go "$SEL" ;; intro) pv_intro_go ;; esac
  [ "$MODE" = small ] && SMALLOF=intro
  while [ -z "$QUIT" ]; do
    [ -n "$WINCHED" ] && { WINCHED=; pv_size; }
    case $MODE in
      intro) [ -n "$CLEAR" ] && { O+=$'\e[2J'; CLEAR=; }; DIRTY=; pv_intro ;;
      menu) if [ -n "$DIRTY" ]; then DIRTY=; pv_menu; else pv_menu_tick; fi ;;
      page) if [ -n "$DIRTY" ]; then DIRTY=; pv_page; else pv_page_tick; fi ;;
      egg|help) [ -n "$DIRTY" ] && { DIRTY=; [ "$BACK" = page ] && pv_page; [ "$BACK" = menu ] && pv_menu; }
        if [ "$MODE" = egg ]; then pv_box "$EGG" $((F - AF0O)); else pv_box "$HELP" 0; fi ;;
      small) [ -n "$DIRTY" ] && { DIRTY=; pv_small; } ;;
    esac
    pv_read
    [ -n "$KB" ] && pv_events
    F=$((F + 1))
  done
}

pv_main "$@"
